        # applies; a newer seal moves the manifest tip past it and the
        # active version stays at that newer version.
        if tip == max(entry["versions"]) and version not in entry["revoked"]:
            entry["active"] = version
        elif tip == max(entry["versions"]):
            # The target existed and was unrevoked when the record was
            # appended; revoking it afterwards is not an error — the
            # redirection simply no longer moves the pointer.
            entry["active"] = max(entry["versions"])

