def test_concurrent_seals_and_redirections_never_tear(self):
    vault = self.open_vault()
    vault.seal("k", b"seed")
    seal_procs, each = 3, 6

    def seal_then_redirect(root: str) -> None:
        v = Vault(root)
        for i in range(each):
            version = v.seal("k", f"m-{i}".encode())
            # The freshly sealed version is active, so redirect at the
            # previous sealed version; racing redirection workers may
            # already hold the pointer there, in which case the
            # documented ValueError is simply ignored.
            if version > 1:
                try:
                    v.set_active("k", version - 1)
                except ValueError:
                    pass
            v.reload()

    workers = [
        multiprocessing.Process(target=seal_then_redirect, args=(str(self.root),))
        for _ in range(seal_procs)
    ]
    workers += [
        multiprocessing.Process(target=_reload_worker, args=(str(self.root), 20))
        for _ in range(2)
    ]
    self._run_workers(workers)

